/// Seed the original cookie before resolver XOR publication. Caller supplies the
/// reconstructed32-bit local frame reference and prior counter words explicitly.
/// Existing root ownership is checked before changing its dispatch cookie.
pub fn initialize_with_cookie<S:Services,E:crate::audio_security_cookie::Services>(mut context:Context<S>,retirement:Option<Retirement<S>>,local_reference:u32,initial_counter:[u32;2],entropy:&mut E)->Result<Startup<S>,Failure>{
 if get(&context.memory,&context.dead,0x12230cc,4).map_err(failure)?!=u32::MAX{return Err(Failure::InvalidContext("CRT root already owns a slot".into()));}
 crate::audio_security_cookie::initialize(&mut context.memory,&context.dead,local_reference,initial_counter,entropy).map_err(failure)?;
 initialize(context,retirement)
}

